<?phpfunction sendWakeOnLan($mac, $broadcast = '255.255.255.255', $port = 9) {    // MAC adresini temizle ve 6 byte'lik ikili hale getir    $mac = strtolower(str_replace(['-', ':'], '', $mac));    if (strlen($mac) != 12) {        throw new Exception("Geçersiz MAC adresi: $mac");    }    $macBinary = '';    for ($i = 0; $i < 12; $i += 2) {        $macBinary .= chr(hexdec(substr($mac, $i, 2)));    }    // Magic Packet: 6 x 0xFF + 16 x MAC adresi    $packet = str_repeat(chr(0xFF), 6) . str_repeat($macBinary, 16);    // UDP soketi olustur    if (!$sock = socket_create(AF_INET, SOCK_DGRAM, SOL_UDP)) {        throw new Exception("Soket olusturulamadi: " . socket_strerror(socket_last_error()));    }    // Broadcast kullanimina izin ver    if (!socket_set_option($sock, SOL_SOCKET, SO_BROADCAST, true)) {        throw new Exception("Broadcast izni verilemedi: " . socket_strerror(socket_last_error($sock)));    }    // UDP üzerinden paketi gönder    $result = socket_sendto($sock, $packet, strlen($packet), 0, $broadcast, $port);    socket_close($sock);    if (!$result) {        throw new Exception("Magic packet gönderilemedi.");    }    return true;}// Kullanim örnegi:try {    sendWakeOnLan("00:09:df:a8:15:0e");    echo "Magic packet gönderildi.\n";} catch (Exception $e) {    echo "Hata: " . $e->getMessage() . "\n";}